const items = $input.all();
let api = items[0]?.json;
if (Array.isArray(api)) api = api[0];

const entrada = $('Start LLM').first().json;
if (!api?.dsc_api_key) throw new Error('CORE LLM: API Key Gemini não encontrada.');
if (!api?.dsc_url_servico) throw new Error('CORE LLM: modelo Gemini não encontrado.');

const modelo = String(api.dsc_url_servico).replace(/^models\//, '').trim();
const system = String(entrada.MSG_Prompt_System ?? '').trim();
const user = String(entrada.MSG_Prompt_User ?? '').trim();
if (!system || !user) throw new Error('CORE LLM: prompts obrigatórios não recebidos.');

let core = { tentativa_gemini: 1, max_tentativas_gemini: 5 };
try {
  const inicial = $('INI CORE').first().json._core;
  if (inicial) {
    core.tentativa_gemini = Number(inicial.tentativa ?? 1);
    core.max_tentativas_gemini = Number(inicial.max_tentativas ?? 5);
  }
} catch {}
try {
  const anterior = $('IF RETRY').last().json.contexto?._core;
  if (anterior) core = { ...core, ...anterior };
} catch {}

return [{
  json: {
    api_id: api.id,
    api_key: api.dsc_api_key,
    modelo,
    txt_CMD_System: system,
    txt_CMD_User: user,
    _core: core,
  },
}];

const item = $input.first()?.json ?? {};
const partes = item.candidates?.[0]?.content?.parts ?? [];
const textoGemini = Array.isArray(partes)
  ? partes.filter(parte => typeof parte?.text === 'string').map(parte => parte.text).join('')
  : '';
const texto = typeof item.text === 'string' ? item.text.trim() : textoGemini.trim();

if (!texto) throw new Error('CORE LLM: resposta textual vazia ou inválida.');

const tokens = item.tokens
  ?? item.usage?.total_tokens
  ?? item.usage?.totalTokens
  ?? item.usageMetadata?.totalTokenCount
  ?? null;

return [{
  json: {
    text: texto,
    modelo: item.modelo ?? item.modelVersion ?? null,
    tokens,
    provedor: item.provedor ?? 'gemini',
  },
}];

const erro = $('Interpretar Gemini').last().json;
const entrada = $('Start LLM').first().json;
let core = { tentativa_gemini: 1, max_tentativas_gemini: 5 };
try {
  const anterior = $('IF RETRY').last().json.contexto?._core;
  if (anterior) core = { ...core, ...anterior };
} catch {}

return [{
  json: {
    _route: 'fallback_cloudflare',
    provedor_origem: 'gemini',
    api_id_gemini: erro.api_id ?? null,
    erro_gemini: erro.erro ?? 'Falha Gemini sem diagnóstico.',
    MSG_Prompt_System: entrada.MSG_Prompt_System,
    MSG_Prompt_User: entrada.MSG_Prompt_User,
    _core: core,
  },
}];

const item = $input.first()?.json ?? {};
const contexto = item.contexto;
const core = contexto?._core;

if (item.provedor !== 'cloudflare' || item._route !== 'error') {
  throw new Error('CORE LLM: entrada fora da rota de falha Cloudflare.');
}
if (!contexto || !core) {
  throw new Error('CORE LLM: contexto de tentativas ausente.');
}

const tentativaAtual = Number(core.tentativa_gemini);
const maxTentativas = Number(core.max_tentativas_gemini);
if (!Number.isInteger(tentativaAtual) || !Number.isInteger(maxTentativas) || tentativaAtual < 1 || maxTentativas < 1) {
  throw new Error('CORE LLM: contador ou limite de tentativas Gemini inválido.');
}
if (tentativaAtual >= maxTentativas) {
  throw new Error('CORE LLM: Cloudflare falhou (' + (item.code ?? 'erro') + '; HTTP ' + (item.status_code ?? 'indisponível') + ') e o limite de ' + maxTentativas + ' tentativas Gemini foi atingido.');
}

return [{
  json: {
    ...item,
    _route: 'retry_gemini',
    contexto: {
      ...contexto,
      _core: {
        ...core,
        tentativa_gemini: tentativaAtual + 1,
        ultimo_provedor: 'gemini',
        motivo_retorno: 'falha_cloudflare',
        ultimo_erro_cloudflare: {
          codigo: item.code ?? null,
          http_status: item.status_code ?? null,
        },
      },
    },
  },
}];

const contexto = $('Preparar Conta Cloudflare').last().json.contexto;
const response = $json ?? {};
const status = Number(response.statusCode ?? 0);
const body = response.body ?? response;
const result = body?.result ?? {};
const text = typeof result.response === 'string' ? result.response.trim() : '';

if (status >= 200 && status < 300 && body.success !== false && text) {
  return [{
    json: {
      _route: 'success',
      provedor: 'cloudflare',
      contexto,
      text,
      modelo: contexto.modelo,
      usage: result.usage ?? null,
    },
  }];
}

let code;
if (status === 429) code = 'LIMIT_EXCEEDED';
else if (status === 401 || status === 403) code = 'AUTHENTICATION_FAILED';
else if (status === 404) code = 'MODEL_UNAVAILABLE';
else if ([408, 425, 500, 502, 503, 504].includes(status) || status === 0) code = 'UPSTREAM_UNAVAILABLE';
else if (status >= 200 && status < 300) code = 'INVALID_RESPONSE';
else if (status >= 400) code = 'CLOUDFLARE_API_ERROR';
else code = 'COMMUNICATION_ERROR';

return [{
  json: {
    _route: 'error',
    provedor: 'cloudflare',
    contexto,
    code,
    status_code: status || null,
    diagnostic: 'Falha na chamada Cloudflare Workers AI.',
  },
}];

function encontrarRegistro(valor, profundidade = 0) {
  if (profundidade > 6 || valor == null || typeof valor !== 'object') return null;
  if (!Array.isArray(valor) && Object.prototype.hasOwnProperty.call(valor, 'dsc_api_key')) return valor;
  for (const item of Object.values(valor)) {
    const registro = encontrarRegistro(item, profundidade + 1);
    if (registro) return registro;
  }
  return null;
}

const api = encontrarRegistro($input.all().map(item => item.json));
if (!api || api.id == null) throw new Error('CORE Cloudflare: nenhuma conta disponível na SP.');

const accountId = String(api.dsc_api_key ?? '').trim();
const apiToken = String(api.dsc_api_secret ?? '').trim();
if (!/^[a-f0-9]{32}$/i.test(accountId)) throw new Error('CORE Cloudflare: Account ID ausente ou inválido no cadastro.');
if (!apiToken) throw new Error('CORE Cloudflare: token ausente no cadastro.');

const entrada = $('Start LLM').first().json;
const system = String(entrada.MSG_Prompt_System ?? '').trim();
const user = String(entrada.MSG_Prompt_User ?? '').trim();
if (!system || !user) throw new Error('CORE Cloudflare: prompts de entrada ausentes.');

let core = { tentativa_gemini: 1, max_tentativas_gemini: 5 };
try {
  const anterior = $('IF RETRY').last().json.contexto?._core;
  if (anterior) core = { ...core, ...anterior };
} catch {}

return [{
  json: {
    contexto: {
      account_id: accountId,
      api_id: api.id,
      api_token: apiToken,
      modelo: '@cf/meta/llama-3.3-70b-instruct-fp8-fast',
      request_body: {
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
        max_tokens: (() => { const value = Number($('Start LLM').first().json.MSG_Max_Tokens); return Number.isInteger(value) && value > 0 ? value : 2048; })(),
        stream: false,
      },
      _core: core,
    },
  },
}];

const payload = $json ?? {};
const gemini = $('Normaliza').first().json;
const candidates = payload.candidates ?? payload.body?.candidates ?? [];
const parts = candidates[0]?.content?.parts ?? [];
const texto = parts.map(p => p?.text ?? '').join('').trim();
const rawErro = payload.error?.message ?? payload.error ?? payload.message ?? payload.body?.error?.message ?? '';
const sucesso = !rawErro && texto.length > 0;
const statusCode = Number(payload.statusCode ?? payload.status ?? payload.error?.code ?? payload.error?.statusCode ?? payload.error?.httpCode ?? 0) || null;
return [{ json: { ...payload, _route: sucesso ? 'success' : 'error', api_id: gemini.api_id, provedor: 'gemini', fallback_provedor: 'cloudflare', modelo: gemini.modelo ?? null, text: sucesso ? texto : '', tokens: payload.usageMetadata?.totalTokenCount ?? null, status_code: statusCode, erro: sucesso ? null : String(rawErro || 'Gemini retornou resposta vazia ou sem candidates válidos.').trim().slice(0, 1000), execution_id: $execution.id, timestamp: $now.toISO(), alerta_tipo: sucesso ? null : 'gemini_fallback' } }];
